"""The video processing pipeline: decode -> AI frame interpolation -> encode.

Design notes
------------
* FFmpeg decodes the source to raw RGB24 on stdout (with scale/crop/pad applied so the
  frames handed to RIFE are exactly the target geometry).
* Every source frame pair is turned into `factor - 1` *new* frames generated by RIFE.
  Fractional factors (e.g. 24 -> 60 fps) are supported by interpolating at fractional
  timesteps along the source timeline.
* A second FFmpeg process encodes the raw frames and muxes the original audio.
* The original upload is never modified.
"""
from __future__ import annotations

import logging
import shutil
import subprocess
import threading
import time
from dataclasses import dataclass
from pathlib import Path

import numpy as np

from .config import TMP_DIR
from .ffmpeg import EncoderChoice, build_decode_command, build_encode_command, choose_encoder
from . import subproc
from .probe import VideoInfo, probe_video
from .rife import RifeEngine, RifeError
from .schemas import PRESET_DIMENSIONS, QUALITY_CQ, JobSettings

logger = logging.getLogger(__name__)


class PipelineError(Exception):
    """A user-facing processing failure."""


class Cancelled(Exception):
    pass


@dataclass
class PipelineResult:
    output_path: Path
    width: int
    height: int
    fps: float
    duration: float
    encoder: str
    encoder_kind: str
    interpolation_factor: float
    interpolated_frames: int
    audio_preserved: bool
    bitrate: int | None = None


@dataclass
class ProgressUpdate:
    stage: str
    message: str
    processed: int
    total: int
    fps: float
    eta: float | None


class PairInterpolator:
    """Produces intermediate frames for one source frame pair.

    Uses the model timestep input when available; otherwise bisects with memoisation so
    fractional timesteps (e.g. 0.2, 0.6) can still be served by a t=0.5-only model.
    """

    def __init__(self, engine: RifeEngine, a: np.ndarray, b: np.ndarray) -> None:
        self.engine = engine
        self.a = a
        self.b = b
        self._cache: dict[int, np.ndarray] = {}  # numerator/256 -> frame
        self.max_depth = 3 if not engine.supports_timestep else 0

    def _snap(self, t: float) -> float:
        if self.engine.supports_timestep:
            return t
        steps = 2 ** self.max_depth
        return round(t * steps) / steps

    def at(self, t: float) -> np.ndarray:
        t = self._snap(t)
        if t <= 1e-6:
            return self.a
        if t >= 1.0 - 1e-6:
            return self.b
        if self.engine.supports_timestep:
            return self.engine.interpolate(self.a, self.b, t)

        key = int(round(t * 256))
        cached = self._cache.get(key)
        if cached is not None:
            return cached

        # Recursive bisection with memoised midpoints.
        lo, hi = self.a, self.b
        lo_t, hi_t = 0.0, 1.0
        # Walk the binary subdivision towards t, remembering midpoints.
        mids: dict[float, np.ndarray] = {}
        for _ in range(self.max_depth):
            mid_t = (lo_t + hi_t) / 2.0
            mid = mids.get(mid_t)
            if mid is None:
                mid = self.engine.interpolate(lo, hi, 0.5)
                mids[mid_t] = mid
            if abs(t - mid_t) < 1e-6:
                self._cache[key] = mid
                return mid
            if t < mid_t:
                hi, hi_t = mid, mid_t
            else:
                lo, lo_t = mid, mid_t
        # t was snapped to a grid point, but rounding landed off-grid; return nearest end.
        result = self.a if abs(t - lo_t) < abs(t - hi_t) else self.b
        self._cache[key] = result
        return result


def resolve_geometry(info: VideoInfo, settings: JobSettings) -> tuple[int, int, str]:
    """Return (width, height, fit_mode) for the processed output."""
    if settings.custom_width and settings.custom_height:
        return _even(settings.custom_width), _even(settings.custom_height), settings.fit_mode

    dims = PRESET_DIMENSIONS.get(settings.preset)
    if dims is None:
        # "original": keep the source resolution, only force even dimensions.
        return _even(info.width), _even(info.height), "original"

    width, height = dims
    if settings.fit_mode == "original":
        # Preset chosen but user wants no scaling/cropping: rotate to vertical only if
        # the source is already vertical-ish, otherwise keep source geometry.
        return _even(info.width), _even(info.height), "original"
    return width, height, settings.fit_mode


def _even(value: int) -> int:
    return value if value % 2 == 0 else value - 1


def compute_frame_size(width: int, height: int, scale: float) -> tuple[int, int]:
    """Frame size the AI interpolates for a given "processing detail" scale.

    Returns the output size unchanged when scale >= 1. Rounds to even dimensions
    because the encoder and the H.264 chroma planes require them.
    """
    if scale >= 1.0 - 1e-9:
        return _even(width), _even(height)
    return _even(max(32, round(width * scale))), _even(max(32, round(height * scale)))


def plan_factor(info: VideoInfo, settings: JobSettings) -> float:
    """Output frames per source frame."""
    speed = settings.slow_motion_speed if settings.slow_motion else 1.0
    denom = info.fps * speed
    if denom <= 0:
        raise PipelineError("Source frame rate is invalid.")
    factor = settings.target_fps / denom
    return factor


def validate_settings(info: VideoInfo, settings: JobSettings) -> None:
    factor = plan_factor(info, settings)
    if factor < 1.0 - 1e-9:
        raise PipelineError(
            f"Target {settings.target_fps} fps is lower than the source ({info.fps:.2f} fps"
            + (f" at {settings.slow_motion_speed}x speed" if settings.slow_motion else "")
            + "). Choose a higher target frame rate."
        )
    if factor > 16:
        raise PipelineError("Requested frame rate increase is too large (max 16x).")
    if settings.slow_motion and info.duration * (1 / settings.slow_motion_speed) > info.duration + 600:
        raise PipelineError("Slow motion would create an excessively long video.")


def check_disk_space(info: VideoInfo, settings: JobSettings, estimated_bitrate_mbps: float) -> None:
    speed = settings.slow_motion_speed if settings.slow_motion else 1.0
    duration_out = info.duration / speed
    estimated_bytes = (estimated_bitrate_mbps * 1_000_000 / 8) * duration_out
    free = shutil.disk_usage(str(TMP_DIR if TMP_DIR.exists() else Path.cwd())).free
    if free < estimated_bytes * 2:
        raise PipelineError(
            "Not enough free disk space for this export "
            f"(need about {estimated_bytes / 1e9:.2f} GB, free {free / 1e9:.2f} GB)."
        )


class _PipeReader(threading.Thread):
    """Drains a process' stderr so it never blocks, keeping the tail for error messages."""

    def __init__(self, stream, label: str, keep_lines: int = 25) -> None:
        super().__init__(daemon=True)
        self.stream = stream
        self.label = label
        self.lines: list[str] = []
        self._keep = keep_lines

    def run(self) -> None:
        try:
            for raw in iter(self.stream.readline, b""):
                line = raw.decode("utf-8", "replace").rstrip()
                if line:
                    self.lines.append(line)
                    if len(self.lines) > self._keep:
                        self.lines.pop(0)
                    logger.debug("[%s] %s", self.label, line)
        except (ValueError, OSError):
            pass

    def tail(self, count: int = 6) -> str:
        return " | ".join(self.lines[-count:])


class VideoPipeline:
    def __init__(self, engine: RifeEngine) -> None:
        self.engine = engine

    def run(
        self,
        *,
        input_path: Path,
        output_path: Path,
        settings: JobSettings,
        info: VideoInfo,
        cancel_event: threading.Event,
        on_progress,
    ) -> PipelineResult:
        validate_settings(info, settings)
        # Tiling decisions are per job (they depend on this frame size and the
        # VRAM that happens to be free right now); do not inherit them forever.
        begin_job = getattr(self.engine, "begin_job", None)
        if begin_job is not None:
            begin_job()

        width, height, fit_mode = resolve_geometry(info, settings)
        factor = plan_factor(info, settings)
        speed = settings.slow_motion_speed if settings.slow_motion else 1.0
        output_fps = info.fps * factor * speed  # in slow motion this equals target_fps

        encoder = choose_encoder(settings.codec, prefer_gpu=settings.prefer_gpu)

        # compute_scale < 1 ("Faster"/"Fastest"): the AI interpolates a smaller frame and
        # the encoder upscales to the real output size. Output geometry is unchanged;
        # cost drops ~1.8x (0.75) or ~4x (0.5) because RIFE cost tracks pixels.
        ai_width, ai_height = width, height
        if settings.compute_scale < 1.0 - 1e-9:
            ai_width, ai_height = compute_frame_size(width, height, settings.compute_scale)
            logger.info(
                "processing detail %g: AI renders %dx%d, upscaled to %dx%d by the encoder",
                settings.compute_scale, ai_width, ai_height, width, height,
            )

        frame_bytes = ai_width * ai_height * 3
        total_src = info.nb_frames or int(round(info.duration * info.fps)) or 1
        total_out = max(int(round(total_src * factor)), 1)

        video_bitrate = None
        if settings.video_bitrate_mbps:
            video_bitrate = f"{settings.video_bitrate_mbps:g}M"
        check_disk_space(info, settings, settings.video_bitrate_mbps or 14.0)

        decode_cmd = build_decode_command(
            str(input_path),
            target_w=ai_width,
            target_h=ai_height,
            fit_mode=fit_mode,
            source_w=info.width,
            source_h=info.height,
        )
        encode_cmd = build_encode_command(
            output_path=str(output_path),
            width=ai_width,
            height=ai_height,
            out_width=width,
            out_height=height,
            output_fps=output_fps,
            encoder=encoder,
            audio_source=str(input_path) if info.has_audio else None,
            quality_cq=QUALITY_CQ.get(settings.quality, 19),
            video_bitrate=video_bitrate,
            audio_bitrate=settings.audio_bitrate,
            audio_speed=speed,
            include_audio=info.has_audio,
        )

        logger.info("decode: %s", " ".join(decode_cmd))
        logger.info("encode: %s", " ".join(encode_cmd))

        decoder = subproc.popen(
            decode_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            bufsize=frame_bytes * 2,
        )
        encoder_proc = subproc.popen(
            encode_cmd, stdin=subprocess.PIPE, stderr=subprocess.PIPE,
            bufsize=frame_bytes * 2,
        )
        dec_err = _PipeReader(decoder.stderr, "decode")
        enc_err = _PipeReader(encoder_proc.stderr, "encode")
        dec_err.start()
        enc_err.start()

        assert decoder.stdout is not None and encoder_proc.stdin is not None
        processed = 0
        interpolated = 0
        started = time.time()
        last_report = 0.0
        next_output = 0

        def emit(frame: np.ndarray) -> None:
            nonlocal next_output, processed, last_report
            encoder_proc.stdin.write(frame.tobytes())
            next_output += 1
            processed += 1
            now = time.time()
            if now - last_report > 0.4 or processed >= total_out:
                last_report = now
                elapsed = now - started
                rate = processed / elapsed if elapsed > 0 else 0.0
                remaining = max(total_out - processed, 0)
                eta = remaining / rate if rate > 0 else None
                on_progress(ProgressUpdate(
                    stage="processing",
                    message=f"Interpolating frames ({processed}/{total_out})",
                    processed=processed,
                    total=total_out,
                    fps=rate,
                    eta=eta,
                ))

        def read_frame() -> np.ndarray | None:
            buf = decoder.stdout.read(frame_bytes)
            if not buf or len(buf) < frame_bytes:
                return None
            # Frames arrive at the AI's compute size, not the final output size.
            return np.frombuffer(buf, dtype=np.uint8).reshape(ai_height, ai_width, 3)

        try:
            on_progress(ProgressUpdate(
                stage="processing",
                message=f"Loading RIFE model on {self.engine.device}",
                processed=0, total=total_out, fps=0.0, eta=None,
            ))

            prev = read_frame()
            if prev is None:
                dec_rc = _wait_with_cancel(decoder, cancel_event, timeout=30)
                detail = dec_err.tail() or f"ffmpeg decode exited with code {dec_rc}"
                raise PipelineError(f"Could not decode any frames from this video. {detail}".strip())

            src_index = 0
            while True:
                if cancel_event.is_set():
                    raise Cancelled()

                curr = read_frame()
                if curr is None:
                    # Last source frame reached: fill remaining output slots with it.
                    while next_output < total_out:
                        if cancel_event.is_set():
                            raise Cancelled()
                        emit(prev)
                    break

                pair = PairInterpolator(self.engine, prev, curr)
                if next_output >= total_out:
                    # The source is longer than the metadata estimate (variable frame rate
                    # or a wrong nb_frames). Extend the plan instead of dropping frames.
                    grow = max(1, int(round(factor)))
                    total_out += grow
                    logger.debug("Source longer than estimated; total_out -> %d", total_out)
                # Emit every output slot whose source position falls inside this pair,
                # i.e. floor(u / factor) == src_index  ->  u in [src_index*factor, (src_index+1)*factor).
                while next_output < total_out:
                    p = next_output / factor
                    if p >= (src_index + 1) - 1e-9:
                        break
                    t = p - src_index
                    if t < 1e-9:
                        emit(prev)  # source frame itself
                    else:
                        emit(pair.at(t))
                        interpolated += 1
                prev = curr
                src_index += 1

            encoder_proc.stdin.close()
            encoder_proc.stdin = None  # type: ignore[assignment]

            on_progress(ProgressUpdate(
                stage="finalizing",
                message="Finalising MP4 (muxing audio)",
                processed=total_out, total=total_out, fps=0.0, eta=0.0,
            ))

            # Wait in small slices so cancelling during muxing (which can take a
            # while on long videos) is honoured instead of blocking for 30 min.
            enc_rc = _wait_with_cancel(encoder_proc, cancel_event, timeout=1800)
            dec_rc = _wait_with_cancel(decoder, cancel_event, timeout=60)
            if dec_rc != 0:
                raise PipelineError(
                    "Decoding failed: " + (dec_err.tail() or f"ffmpeg exited with code {dec_rc}")
                )
            if enc_rc != 0:
                raise PipelineError(
                    "Encoding failed: " + (enc_err.tail() or f"ffmpeg exited with code {enc_rc}")
                )
            if not output_path.exists() or output_path.stat().st_size == 0:
                raise PipelineError("Encoding produced no output file.")
        except Cancelled:
            _terminate(decoder, encoder_proc)
            raise
        except (BrokenPipeError, OSError) as exc:
            _terminate(decoder, encoder_proc)
            # Give the stderr readers a moment to drain so the real ffmpeg message is
            # reported instead of an empty tail.
            enc_err.join(timeout=1.0)
            dec_err.join(timeout=1.0)
            detail = enc_err.tail() or dec_err.tail()
            raise PipelineError(f"FFmpeg pipe error: {exc}. {detail}".strip()) from exc
        except Exception:
            _terminate(decoder, encoder_proc)
            raise

        enhanced = probe_video(str(output_path))
        return PipelineResult(
            output_path=output_path,
            width=enhanced.width,
            height=enhanced.height,
            fps=enhanced.fps,
            duration=enhanced.duration,
            encoder=encoder.name,
            encoder_kind=encoder.kind,
            interpolation_factor=factor,
            interpolated_frames=interpolated,
            audio_preserved=enhanced.has_audio,
            bitrate=enhanced.bitrate,
        )


def _wait_with_cancel(
    proc: subprocess.Popen,
    cancel_event: threading.Event,
    *,
    timeout: float,
    poll_interval: float = 0.2,
) -> int:
    """Wait for a child process while honouring the job's cancellation flag."""
    deadline = time.monotonic() + timeout
    while proc.poll() is None:
        if cancel_event.is_set():
            raise Cancelled()
        if time.monotonic() >= deadline:
            raise PipelineError("FFmpeg did not finish in time.")
        time.sleep(poll_interval)
    return int(proc.returncode or 0)


def _terminate(*procs: subprocess.Popen) -> None:
    for proc in procs:
        if proc is None or proc.poll() is not None:
            continue
        try:
            if proc.stdin and not proc.stdin.closed:
                proc.stdin.close()
        except OSError:
            pass
        try:
            proc.kill()
        except OSError:
            pass
        # Reap the process: on Windows an exited-but-unreaped child can still hold the
        # output file handle open, which would make the caller's unlink() fail and
        # leave a partial MP4 behind.
        try:
            proc.wait(timeout=10)
        except (subprocess.TimeoutExpired, OSError):
            pass
